import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-DzSRHLA0.js";var o=JSON.parse(`{"path":"/Linux/01_Linux%E5%9F%BA%E7%A1%80/02_%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E4%B8%8E%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84.html","title":"文件系统与目录结构","lang":"zh-CN","frontmatter":{"title":"文件系统与目录结构","icon":"fa6-solid:folder-tree","order":2,"category":["Linux基础"],"tag":["文件系统","FHS","inode","链接","目录结构"]},"git":{"createdTime":1780586585000,"updatedTime":1780586585000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":22.38,"words":6713},"filePathRelative":"Linux/01_Linux基础/02_文件系统与目录结构.md"}`),s={name:`02_文件系统与目录结构.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="文件系统与目录结构" tabindex="-1"><a class="header-anchor" href="#文件系统与目录结构"><span>文件系统与目录结构</span></a></h1><p>&quot;在 Linux 中，一切皆文件&quot;——这句话概括了 Linux 文件系统设计的核心理念。无论是普通文件、目录、设备、管道还是 Socket，都以文件的形式呈现在统一的目录树中。本文从 FHS 标准出发，逐层剖析每个目录的用途，深入 inode 与数据块的关系，讲透硬链接与软链接的本质区别。</p><h2 id="_1-一切皆文件-的哲学" tabindex="-1"><a class="header-anchor" href="#_1-一切皆文件-的哲学"><span>1. &quot;一切皆文件&quot;的哲学</span></a></h2><h3 id="_1-1-什么是-一切皆文件" tabindex="-1"><a class="header-anchor" href="#_1-1-什么是-一切皆文件"><span>1.1 什么是&quot;一切皆文件&quot;</span></a></h3><p>Linux 继承了 UNIX 的设计哲学：用统一的文件接口来访问所有资源。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 普通文件</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /etc/hostname</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 目录也是文件（存储了文件名与 inode 的映射）</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /home</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 设备也是文件</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /dev/null</span><span style="color:#7F848E;font-style:italic;">          # 黑洞设备</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;hello&quot;</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/dev/tty</span><span style="color:#7F848E;font-style:italic;">   # 写入终端设备</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 进程信息也是文件</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /proc/cpuinfo</span><span style="color:#7F848E;font-style:italic;">      # CPU 信息</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /proc/meminfo</span><span style="color:#7F848E;font-style:italic;">      # 内存信息</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 网络连接也是文件</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /proc/self/fd/</span><span style="color:#7F848E;font-style:italic;">  # 当前进程的文件描述符</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 0 -&gt; stdin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1 -&gt; stdout</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2 -&gt; stderr</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-文件类型标识" tabindex="-1"><a class="header-anchor" href="#_1-2-文件类型标识"><span>1.2 文件类型标识</span></a></h3><p>使用 <code>ls -l</code> 命令查看文件时，第一个字符表示文件类型：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>-rw-r--r-- 1 root root 1234 Jun  4 10:00 example.txt</span></span>
<span class="line"><span>^</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 文件类型标识符</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>标识</th><th>类型</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>-</code></td><td>普通文件</td><td>文本、二进制、图片等</td><td><code>file.txt</code>、<code>/bin/ls</code></td></tr><tr><td><code>d</code></td><td>目录文件</td><td>存储文件名与 inode 映射</td><td><code>/home</code>、<code>/etc</code></td></tr><tr><td><code>l</code></td><td>符号链接</td><td>指向另一个文件的路径</td><td><code>/usr/bin/python</code> → <code>python3</code></td></tr><tr><td><code>b</code></td><td>块设备</td><td>按块读写的设备</td><td><code>/dev/sda</code>（硬盘）</td></tr><tr><td><code>c</code></td><td>字符设备</td><td>按字节读写的设备</td><td><code>/dev/tty</code>（终端）</td></tr><tr><td><code>p</code></td><td>管道（FIFO）</td><td>进程间通信</td><td><code>mkfifo /tmp/mypipe</code></td></tr><tr><td><code>s</code></td><td>套接字</td><td>网络通信</td><td><code>/var/run/docker.sock</code></td></tr></tbody></table><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看文件类型</span></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /etc/passwd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/passwd: ASCII text</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /bin/ls</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /bin/ls: ELF 64-bit LSB executable</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /dev/sda</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda: block special (8/0)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /dev/null</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/null: character special (1/3)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 统计各类型文件数量</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /dev</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">awk</span><span style="color:#98C379;"> &#39;{print $1}&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">cut</span><span style="color:#D19A66;"> -c1</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">uniq</span><span style="color:#D19A66;"> -c</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rn</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-fhs-标准" tabindex="-1"><a class="header-anchor" href="#_2-fhs-标准"><span>2. FHS 标准</span></a></h2><h3 id="_2-1-什么是-fhs" tabindex="-1"><a class="header-anchor" href="#_2-1-什么是-fhs"><span>2.1 什么是 FHS</span></a></h3><p><strong>FHS</strong>（Filesystem Hierarchy Standard，文件系统层次标准）定义了 Linux 系统中目录的结构和用途，由 Linux 基金会维护。FHS 的目标是让用户和程序能预测已安装文件和目录的位置。</p>`,14),i(d,{code:``}),o[1]||=n(`<h3 id="_2-2-fhs-的两大分类" tabindex="-1"><a class="header-anchor" href="#_2-2-fhs-的两大分类"><span>2.2 FHS 的两大分类</span></a></h3><p>FHS 将目录中的内容分为两大类：</p><table><thead><tr><th>分类</th><th>特征</th><th>可否共享</th><th>可否只读</th><th>代表目录</th></tr></thead><tbody><tr><td><strong>可共享文件</strong></td><td>可被网络中多台主机共用</td><td>✅</td><td>✅</td><td><code>/usr</code>、<code>/home</code>、<code>/var/mail</code></td></tr><tr><td><strong>不可共享文件</strong></td><td>仅限本机使用</td><td>❌</td><td>视情况</td><td><code>/etc</code>、<code>/var/run</code>、<code>/boot</code></td></tr><tr><td><strong>静态文件</strong></td><td>除非系统管理员操作，不会变化</td><td>-</td><td>✅</td><td><code>/bin</code>、<code>/lib</code>、<code>/usr/bin</code></td></tr><tr><td><strong>可变文件</strong></td><td>系统运行过程中会频繁变化</td><td>-</td><td>❌</td><td><code>/var/log</code>、<code>/home</code>、<code>/tmp</code></td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">为什么区分可共享/不可共享？</p><p>在大型企业环境中，<code>/usr</code> 可以通过 NFS 共享给多台工作站，节省磁盘空间。而 <code>/etc</code> 包含每台机器独有的配置（如主机名、IP），不可共享。这种分类指导了网络文件系统的挂载策略。</p></div><h2 id="_3-核心目录详解" tabindex="-1"><a class="header-anchor" href="#_3-核心目录详解"><span>3. 核心目录详解</span></a></h2><h3 id="_3-1-根目录" tabindex="-1"><a class="header-anchor" href="#_3-1-根目录"><span>3.1 / 根目录</span></a></h3><p>根目录是整个文件系统的起点，FHS 要求根目录下<strong>必须</strong>包含以下子目录：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 根目录下的标准子目录</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - bin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - boot</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - dev</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - etc</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - home</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - lib</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - media</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - mnt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - opt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - proc</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - root</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - sbin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - srv</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - sys</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - tmp</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - usr</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># drwxr-xr-x   - var</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">根目录的设计原则</p><ol><li>根目录应尽量小——这样启动、恢复、修复更容易</li><li>根分区应能在单用户模式下被挂载</li><li>不要在根目录下随意创建文件或目录</li></ol></div><h3 id="_3-2-etc-——-系统配置" tabindex="-1"><a class="header-anchor" href="#_3-2-etc-——-系统配置"><span>3.2 /etc —— 系统配置</span></a></h3><p><code>/etc</code> 是 Linux 中最重要的配置目录，几乎所有服务的配置文件都存放在此。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 重要配置文件一览</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/passwd</span><span style="color:#7F848E;font-style:italic;">          # 用户账户信息</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/shadow</span><span style="color:#7F848E;font-style:italic;">          # 用户密码（加密后）</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/group</span><span style="color:#7F848E;font-style:italic;">           # 用户组信息</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/hostname</span><span style="color:#7F848E;font-style:italic;">        # 主机名</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/hosts</span><span style="color:#7F848E;font-style:italic;">           # 静态 DNS 映射</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/resolv.conf</span><span style="color:#7F848E;font-style:italic;">     # DNS 解析配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/fstab</span><span style="color:#7F848E;font-style:italic;">           # 文件系统挂载表</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/crontab</span><span style="color:#7F848E;font-style:italic;">         # 系统定时任务</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/sudoers</span><span style="color:#7F848E;font-style:italic;">         # sudo 权限配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/ssh/</span><span style="color:#7F848E;font-style:italic;">            # SSH 服务配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/nginx/</span><span style="color:#7F848E;font-style:italic;">          # Nginx 配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/systemd/</span><span style="color:#7F848E;font-style:italic;">        # systemd 配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/apt/</span><span style="color:#7F848E;font-style:italic;">            # APT 包管理配置</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/yum.repos.d/</span><span style="color:#7F848E;font-style:italic;">    # YUM 仓库配置</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">etymology</p><p><code>/etc</code> 的 &quot;etc&quot; 不是 &quot;et cetera&quot;（等等）的缩写，而是早期 UNIX 中的 &quot;et cetera directory&quot;——存放&quot;其他&quot;不属于别处的配置文件。随着系统演进，它逐渐成为了专门的配置目录。</p></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 配置文件编辑的最佳实践</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 修改前备份</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> cp</span><span style="color:#98C379;"> /etc/ssh/sshd_config</span><span style="color:#98C379;"> /etc/ssh/sshd_config.bak</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 使用 visudo 编辑 sudoers（自动语法检查）</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> visudo</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 使用 systemctl edit 编辑 systemd 配置（自动创建 override）</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> systemctl</span><span style="color:#98C379;"> edit</span><span style="color:#98C379;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 验证配置语法</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> nginx</span><span style="color:#D19A66;"> -t</span><span style="color:#7F848E;font-style:italic;">          # Nginx</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> apachectl</span><span style="color:#98C379;"> configtest</span><span style="color:#7F848E;font-style:italic;">  # Apache</span></span>
<span class="line"><span style="color:#61AFEF;">sshd</span><span style="color:#D19A66;"> -t</span><span style="color:#7F848E;font-style:italic;">                # SSH</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-var-——-可变数据" tabindex="-1"><a class="header-anchor" href="#_3-3-var-——-可变数据"><span>3.3 /var —— 可变数据</span></a></h3><p><code>/var</code> 存放在系统运行过程中不断变化的数据：日志、缓存、邮件、队列等。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /var 目录结构</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/</span><span style="color:#7F848E;font-style:italic;">             # 日志文件</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/syslog</span><span style="color:#7F848E;font-style:italic;">       # 系统日志（Debian/Ubuntu）</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/messages</span><span style="color:#7F848E;font-style:italic;">     # 系统日志（RHEL/CentOS）</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/auth.log</span><span style="color:#7F848E;font-style:italic;">     # 认证日志</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/kern.log</span><span style="color:#7F848E;font-style:italic;">     # 内核日志</span></span>
<span class="line"><span style="color:#61AFEF;">/var/log/nginx/</span><span style="color:#7F848E;font-style:italic;">       # Nginx 日志</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">/var/cache/</span><span style="color:#7F848E;font-style:italic;">           # 应用缓存</span></span>
<span class="line"><span style="color:#61AFEF;">/var/cache/apt/</span><span style="color:#7F848E;font-style:italic;">       # APT 包缓存</span></span>
<span class="line"><span style="color:#61AFEF;">/var/cache/yum/</span><span style="color:#7F848E;font-style:italic;">       # YUM 包缓存</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">/var/lib/</span><span style="color:#7F848E;font-style:italic;">             # 应用持久状态数据</span></span>
<span class="line"><span style="color:#61AFEF;">/var/lib/mysql/</span><span style="color:#7F848E;font-style:italic;">       # MySQL 数据</span></span>
<span class="line"><span style="color:#61AFEF;">/var/lib/docker/</span><span style="color:#7F848E;font-style:italic;">      # Docker 数据</span></span>
<span class="line"><span style="color:#61AFEF;">/var/lib/rpm/</span><span style="color:#7F848E;font-style:italic;">         # RPM 数据库</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">/var/spool/</span><span style="color:#7F848E;font-style:italic;">           # 队列数据</span></span>
<span class="line"><span style="color:#61AFEF;">/var/spool/cron/</span><span style="color:#7F848E;font-style:italic;">      # 定时任务</span></span>
<span class="line"><span style="color:#61AFEF;">/var/spool/mail/</span><span style="color:#7F848E;font-style:italic;">      # 邮件队列</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">/var/run/</span><span style="color:#7F848E;font-style:italic;">             # 运行时数据（PID 文件、Socket）→ 实际是 /run 的软链接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">日志文件管理</p><p><code>/var/log</code> 是磁盘空间的&quot;黑洞&quot;。如果不加管理，日志文件会无限增长直到磁盘满。务必配置 <strong>logrotate</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 logrotate 配置</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /etc/logrotate.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看特定服务的日志轮转配置</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#98C379;"> /etc/logrotate.d/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># nginx  mysql  syslog  ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 手动触发轮转</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> logrotate</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /etc/logrotate.d/nginx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="_3-4-usr-——-用户级程序" tabindex="-1"><a class="header-anchor" href="#_3-4-usr-——-用户级程序"><span>3.4 /usr —— 用户级程序</span></a></h3><p><code>/usr</code> 是第二大目录树，包含了用户级别的应用程序和文件。FHS 中有一个著名的说法：&quot;/usr is the second major section of the filesystem&quot;。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /usr 的结构（类似一个&quot;次级根目录&quot;）</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/bin/</span><span style="color:#7F848E;font-style:italic;">             # 用户命令</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/sbin/</span><span style="color:#7F848E;font-style:italic;">            # 非必需的系统管理命令</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/lib/</span><span style="color:#7F848E;font-style:italic;">             # 库文件</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/include/</span><span style="color:#7F848E;font-style:italic;">         # C/C++ 头文件</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/share/</span><span style="color:#7F848E;font-style:italic;">           # 架构无关的共享数据</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/share/doc/</span><span style="color:#7F848E;font-style:italic;">       # 文档</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/share/man/</span><span style="color:#7F848E;font-style:italic;">       # man 手册页</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/share/locale/</span><span style="color:#7F848E;font-style:italic;">    # 语言翻译文件</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/local/</span><span style="color:#7F848E;font-style:italic;">           # 本地编译安装的软件</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/local/bin/</span><span style="color:#7F848E;font-style:italic;">       # 本地安装的命令</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/local/lib/</span><span style="color:#7F848E;font-style:italic;">       # 本地安装的库</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">/usr vs /usr/local</p><ul><li><code>/usr</code> 中的文件由<strong>包管理器</strong>管理（apt/yum/dnf）</li><li><code>/usr/local</code> 中的文件由<strong>本地管理员</strong>管理（手动编译安装）</li><li>包管理器不会覆盖 <code>/usr/local</code> 中的文件，两者互不干扰</li></ul></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/bin 与 /bin 的关系</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在现代 Linux 中，/bin 通常是指向 /usr/bin 的软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /bin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 root root 7 /bin -&gt; usr/bin</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /sbin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 root root 8 /sbin -&gt; usr/sbin</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /lib</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 root root 7 /lib -&gt; usr/lib</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 这是 &quot;usr merge&quot; 趋势</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Fedora 从 Fedora 17 开始合并</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Debian 从 Debian Bullseye 开始合并</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-home-——-用户主目录" tabindex="-1"><a class="header-anchor" href="#_3-5-home-——-用户主目录"><span>3.5 /home —— 用户主目录</span></a></h3><p>每个普通用户在 <code>/home</code> 下拥有一个以用户名命名的目录：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 用户主目录</span></span>
<span class="line"><span style="color:#61AFEF;">/home/alice/</span></span>
<span class="line"><span style="color:#61AFEF;">/home/bob/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 主目录下的隐藏配置文件（以 . 开头）</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /home/alice/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .bashrc          # Bash 配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .bash_profile    # Bash 登录配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .profile         # 通用登录配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .ssh/            # SSH 密钥和配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .config/         # XDG 配置目录</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .local/          # 用户级安装</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .local/bin/      # 用户级命令</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># .cache/          # 用户级缓存</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># root 用户的主目录不在 /home 下</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $HOME</span><span style="color:#7F848E;font-style:italic;">    # root 用户：/root</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $HOME</span><span style="color:#7F848E;font-style:italic;">    # 普通用户：/home/username</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-6-proc-——-虚拟文件系统" tabindex="-1"><a class="header-anchor" href="#_3-6-proc-——-虚拟文件系统"><span>3.6 /proc —— 虚拟文件系统</span></a></h3><p><code>/proc</code> 是一个虚拟文件系统（procfs），不占用磁盘空间，内容由内核动态生成：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 进程信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/self/</span><span style="color:#7F848E;font-style:italic;">           # 当前进程信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/1/</span><span style="color:#7F848E;font-style:italic;">              # PID=1 的进程（systemd/init）</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/PID/cmdline</span><span style="color:#7F848E;font-style:italic;">     # 进程启动命令</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/PID/environ</span><span style="color:#7F848E;font-style:italic;">     # 进程环境变量</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/PID/fd/</span><span style="color:#7F848E;font-style:italic;">         # 进程打开的文件描述符</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/PID/status</span><span style="color:#7F848E;font-style:italic;">      # 进程状态</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 内核信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/cpuinfo</span><span style="color:#7F848E;font-style:italic;">         # CPU 信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/meminfo</span><span style="color:#7F848E;font-style:italic;">         # 内存信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/version</span><span style="color:#7F848E;font-style:italic;">         # 内核版本</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/cmdline</span><span style="color:#7F848E;font-style:italic;">         # 内核启动参数</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/modules</span><span style="color:#7F848E;font-style:italic;">         # 已加载模块</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 系统信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/loadavg</span><span style="color:#7F848E;font-style:italic;">         # 负载均值</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/uptime</span><span style="color:#7F848E;font-style:italic;">          # 运行时间</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/mounts</span><span style="color:#7F848E;font-style:italic;">          # 挂载信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/partitions</span><span style="color:#7F848E;font-style:italic;">      # 分区信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/interrupts</span><span style="color:#7F848E;font-style:italic;">      # 中断信息</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/filesystems</span><span style="color:#7F848E;font-style:italic;">     # 支持的文件系统类型</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 可写接口（调整内核参数）</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/sys/vm/swappiness</span><span style="color:#7F848E;font-style:italic;">       # swap 倾向</span></span>
<span class="line"><span style="color:#61AFEF;">/proc/sys/net/ipv4/ip_forward</span><span style="color:#7F848E;font-style:italic;"> # IP 转发</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 实用示例</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 CPU 型号</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> &quot;model name&quot;</span><span style="color:#98C379;"> /proc/cpuinfo</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看内存使用</span></span>
<span class="line"><span style="color:#61AFEF;">free</span><span style="color:#D19A66;"> -h</span><span style="color:#7F848E;font-style:italic;">    # 等同于读取 /proc/meminfo</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看进程打开了哪些文件</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /proc/</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">pidof</span><span style="color:#98C379;"> nginx</span><span style="color:#ABB2BF;">)</span><span style="color:#98C379;">/fd/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看进程的环境变量</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /proc/</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">pidof</span><span style="color:#98C379;"> nginx</span><span style="color:#ABB2BF;">)</span><span style="color:#98C379;">/environ</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#98C379;"> &#39;\\0&#39;</span><span style="color:#98C379;"> &#39;\\n&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 实时调整内核参数</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> sysctl</span><span style="color:#98C379;"> vm.swappiness=</span><span style="color:#D19A66;">10</span><span style="color:#7F848E;font-style:italic;">     # 等同于写入 /proc/sys/vm/swappiness</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">/proc 文件的特殊性</p><ol><li><code>/proc</code> 中的文件大小显示为 0，但读取时有内容</li><li>不要用文本编辑器直接编辑 <code>/proc/sys/</code> 下的文件，使用 <code>sysctl</code> 命令</li><li><code>/proc/PID/</code> 目录在进程结束后自动消失</li></ol></div><h3 id="_3-7-sys-——-内核设备树" tabindex="-1"><a class="header-anchor" href="#_3-7-sys-——-内核设备树"><span>3.7 /sys —— 内核设备树</span></a></h3><p><code>/sys</code>（sysfs）是 Linux 2.6 引入的虚拟文件系统，用于向用户空间导出内核对象（kobject）的层次结构：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /sys 的结构</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/block/</span><span style="color:#7F848E;font-style:italic;">           # 块设备</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/bus/</span><span style="color:#7F848E;font-style:italic;">             # 设备总线</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/class/</span><span style="color:#7F848E;font-style:italic;">           # 设备按类别分类</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/class/net/</span><span style="color:#7F848E;font-style:italic;">       # 网络设备</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/class/block/</span><span style="color:#7F848E;font-style:italic;">     # 块设备</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/dev/</span><span style="color:#7F848E;font-style:italic;">             # 设备按主次设备号</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/devices/</span><span style="color:#7F848E;font-style:italic;">         # 所有设备的物理拓扑</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/fs/</span><span style="color:#7F848E;font-style:italic;">              # 文件系统参数</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/kernel/</span><span style="color:#7F848E;font-style:italic;">          # 内核参数</span></span>
<span class="line"><span style="color:#61AFEF;">/sys/module/</span><span style="color:#7F848E;font-style:italic;">          # 已加载模块</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 实用示例</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看块设备信息</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#98C379;"> /sys/block/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># sda  sr0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看网卡信息</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#98C379;"> /sys/class/net/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># eth0  lo</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 CPU 频率（可调节）</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看电池状态（笔记本）</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /sys/class/power_supply/BAT0/capacity</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 85</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-8-dev-——-设备文件" tabindex="-1"><a class="header-anchor" href="#_3-8-dev-——-设备文件"><span>3.8 /dev —— 设备文件</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /dev 中的常见设备文件</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/sda</span><span style="color:#7F848E;font-style:italic;">              # 第一块 SCSI/SATA 硬盘</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/sda1</span><span style="color:#7F848E;font-style:italic;">             # 第一块硬盘的第一个分区</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/nvme0n1</span><span style="color:#7F848E;font-style:italic;">          # 第一块 NVMe SSD</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/nvme0n1p1</span><span style="color:#7F848E;font-style:italic;">        # NVMe SSD 的第一个分区</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/tty</span><span style="color:#7F848E;font-style:italic;">              # 当前终端</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/tty0~tty6</span><span style="color:#7F848E;font-style:italic;">        # 虚拟控制台</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/pts/0~</span><span style="color:#7F848E;font-style:italic;">           # 伪终端（SSH 远程登录）</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/null</span><span style="color:#7F848E;font-style:italic;">             # 黑洞（丢弃所有写入）</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/zero</span><span style="color:#7F848E;font-style:italic;">             # 零字节流</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/random</span><span style="color:#7F848E;font-style:italic;">           # 随机数（阻塞）</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/urandom</span><span style="color:#7F848E;font-style:italic;">          # 随机数（非阻塞）</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/loop0~</span><span style="color:#7F848E;font-style:italic;">           # 回环设备</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># udev 规则</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev 下的设备文件由 udev 动态创建</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 自定义规则在 /etc/udev/rules.d/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 实用操作</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 创建空文件（1GB）</span></span>
<span class="line"><span style="color:#61AFEF;">dd</span><span style="color:#98C379;"> if=/dev/zero</span><span style="color:#98C379;"> of=test.img</span><span style="color:#98C379;"> bs=1M</span><span style="color:#98C379;"> count=</span><span style="color:#D19A66;">1024</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 安全擦除磁盘</span></span>
<span class="line"><span style="color:#61AFEF;">dd</span><span style="color:#98C379;"> if=/dev/urandom</span><span style="color:#98C379;"> of=/dev/sda</span><span style="color:#98C379;"> bs=1M</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 丢弃输出</span></span>
<span class="line"><span style="color:#56B6C2;">command</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> 2&gt;&amp;1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 生成随机密码</span></span>
<span class="line"><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -c</span><span style="color:#D19A66;"> 16</span><span style="color:#98C379;"> /dev/urandom</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">base64</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-9-其他目录" tabindex="-1"><a class="header-anchor" href="#_3-9-其他目录"><span>3.9 其他目录</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /boot - 启动文件</span></span>
<span class="line"><span style="color:#61AFEF;">/boot/vmlinuz-*</span><span style="color:#7F848E;font-style:italic;">       # 内核镜像</span></span>
<span class="line"><span style="color:#61AFEF;">/boot/initramfs-*</span><span style="color:#7F848E;font-style:italic;">     # 初始 RAM 文件系统</span></span>
<span class="line"><span style="color:#61AFEF;">/boot/grub/</span><span style="color:#7F848E;font-style:italic;">           # GRUB 引导加载器配置</span></span>
<span class="line"><span style="color:#61AFEF;">/boot/efi/</span><span style="color:#7F848E;font-style:italic;">            # EFI 系统分区（UEFI 启动）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /tmp - 临时文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 所有用户可写，系统重启时通常清空</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 现代 Linux 使用 tmpfs（内存文件系统）</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -T</span><span style="color:#98C379;"> /tmp</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 文件系统    类型   ...</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># tmpfs      tmpfs  ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /opt - 第三方软件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 独立安装的商业软件</span></span>
<span class="line"><span style="color:#61AFEF;">/opt/google/chrome/</span></span>
<span class="line"><span style="color:#61AFEF;">/opt/cuda/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /srv - 服务数据</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 此目录存放服务相关的数据（较少使用）</span></span>
<span class="line"><span style="color:#61AFEF;">/srv/www/</span><span style="color:#7F848E;font-style:italic;">            # Web 数据</span></span>
<span class="line"><span style="color:#61AFEF;">/srv/ftp/</span><span style="color:#7F848E;font-style:italic;">            # FTP 数据</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /media - 可移动设备自动挂载</span></span>
<span class="line"><span style="color:#61AFEF;">/media/username/USB_DRIVE/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /mnt - 临时手动挂载</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mount</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#98C379;"> /mnt/usb</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-绝对路径与相对路径" tabindex="-1"><a class="header-anchor" href="#_4-绝对路径与相对路径"><span>4. 绝对路径与相对路径</span></a></h2><h3 id="_4-1-路径类型" tabindex="-1"><a class="header-anchor" href="#_4-1-路径类型"><span>4.1 路径类型</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 绝对路径：从根目录 / 开始的完整路径</span></span>
<span class="line"><span style="color:#61AFEF;">/etc/passwd</span></span>
<span class="line"><span style="color:#61AFEF;">/home/alice/.bashrc</span></span>
<span class="line"><span style="color:#61AFEF;">/usr/local/bin/python3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 相对路径：从当前目录开始的路径</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> Documents/</span><span style="color:#7F848E;font-style:italic;">         # 进入当前目录下的 Documents</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ..</span><span style="color:#7F848E;font-style:italic;">                 # 返回上级目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ../..</span><span style="color:#7F848E;font-style:italic;">              # 返回上两级目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ./scripts/</span><span style="color:#7F848E;font-style:italic;">         # 当前目录下的 scripts（./ 可省略）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 特殊路径</span></span>
<span class="line"><span style="color:#56B6C2;">.</span><span style="color:#7F848E;font-style:italic;">                     # 当前目录</span></span>
<span class="line"><span style="color:#56B6C2;">..</span><span style="color:#7F848E;font-style:italic;">                    # 上级目录</span></span>
<span class="line"><span style="color:#ABB2BF;">~                     </span><span style="color:#7F848E;font-style:italic;"># 当前用户主目录</span></span>
<span class="line"><span style="color:#ABB2BF;">~-                    </span><span style="color:#7F848E;font-style:italic;"># 上一次所在目录</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-路径操作命令" tabindex="-1"><a class="header-anchor" href="#_4-2-路径操作命令"><span>4.2 路径操作命令</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># pwd - 显示当前绝对路径</span></span>
<span class="line"><span style="color:#56B6C2;">pwd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /home/alice/projects</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cd - 切换目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> /etc</span><span style="color:#7F848E;font-style:italic;">               # 绝对路径</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ssh</span><span style="color:#7F848E;font-style:italic;">                # 相对路径</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> ~</span><span style="color:#7F848E;font-style:italic;">                  # 回到主目录</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> -</span><span style="color:#7F848E;font-style:italic;">                  # 回到上一次目录</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># realpath - 获取真实路径（解析符号链接）</span></span>
<span class="line"><span style="color:#61AFEF;">realpath</span><span style="color:#98C379;"> /usr/bin/python</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/bin/python3.10</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># dirname - 获取目录部分</span></span>
<span class="line"><span style="color:#61AFEF;">dirname</span><span style="color:#98C379;"> /etc/nginx/nginx.conf</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/nginx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># basename - 获取文件名部分</span></span>
<span class="line"><span style="color:#61AFEF;">basename</span><span style="color:#98C379;"> /etc/nginx/nginx.conf</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># nginx.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># readlink - 读取符号链接目标</span></span>
<span class="line"><span style="color:#61AFEF;">readlink</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> /usr/bin/python</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/bin/python3.10  (-f 递归解析所有链接)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-path-环境变量" tabindex="-1"><a class="header-anchor" href="#_4-3-path-环境变量"><span>4.3 PATH 环境变量</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># PATH 决定了 Shell 在哪些目录中搜索命令</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#E06C75;"> $PATH</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看命令的位置</span></span>
<span class="line"><span style="color:#56B6C2;">which</span><span style="color:#98C379;"> python3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/bin/python3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">whereis</span><span style="color:#98C379;"> nginx</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># nginx: /usr/sbin/nginx /etc/nginx /usr/share/nginx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 临时添加 PATH</span></span>
<span class="line"><span style="color:#C678DD;">export</span><span style="color:#E06C75;"> PATH</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;/opt/bin:</span><span style="color:#E06C75;">$PATH</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久添加（写入 ~/.bashrc 或 ~/.profile）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;export PATH=&quot;/opt/bin:$PATH&quot;&#39;</span><span style="color:#ABB2BF;"> &gt;&gt; </span><span style="color:#98C379;">~/.bashrc</span></span>
<span class="line"><span style="color:#56B6C2;">source</span><span style="color:#98C379;"> ~/.bashrc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">PATH 的安全风险</p><p>永远不要将 <code>.</code>（当前目录）放在 PATH 的前面！否则攻击者可以在常用目录放置恶意程序，当你执行 <code>ls</code> 时实际运行的是恶意脚本。这就是为什么 Linux 不像 Windows 那样在当前目录搜索可执行文件。</p></div><h2 id="_5-inode-与数据块" tabindex="-1"><a class="header-anchor" href="#_5-inode-与数据块"><span>5. inode 与数据块</span></a></h2><h3 id="_5-1-inode-是什么" tabindex="-1"><a class="header-anchor" href="#_5-1-inode-是什么"><span>5.1 inode 是什么</span></a></h3><p><strong>inode</strong>（index node，索引节点）是文件系统中最核心的数据结构。每个文件（包括目录）都有一个唯一的 inode，存储了文件的<strong>元数据</strong>（除文件名和文件内容之外的所有信息）。</p>`,50),i(d,{code:``}),o[2]||=n(`<h3 id="_5-2-inode-包含的信息" tabindex="-1"><a class="header-anchor" href="#_5-2-inode-包含的信息"><span>5.2 inode 包含的信息</span></a></h3><table><thead><tr><th>信息</th><th>说明</th><th>查看命令</th></tr></thead><tbody><tr><td>文件权限</td><td>rwx 权限位</td><td><code>ls -l</code></td></tr><tr><td>所有者 UID</td><td>文件属主</td><td><code>ls -l -n</code></td></tr><tr><td>所属组 GID</td><td>文件属组</td><td><code>ls -l -n</code></td></tr><tr><td>文件大小</td><td>字节数</td><td><code>ls -l</code></td></tr><tr><td>时间戳</td><td>atime/mtime/ctime</td><td><code>stat</code></td></tr><tr><td>硬链接数</td><td>指向此 inode 的目录项数</td><td><code>ls -l</code> 第二列</td></tr><tr><td>数据块指针</td><td>直接/间接指针</td><td><code>debugfs</code></td></tr><tr><td><strong>不包含</strong></td><td><strong>文件名</strong></td><td>文件名存在目录项中</td></tr></tbody></table><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 inode 信息</span></span>
<span class="line"><span style="color:#56B6C2;">stat</span><span style="color:#98C379;"> example.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   File: example.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   Size: 1234            Blocks: 8          IO Block: 4096   regular file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Device: 802h/2050d      Inode: 12345       Links: 1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Access: (0644/-rw-r--r--)  Uid: ( 1000/  alice)   Gid: ( 1000/  alice)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Access: 2024-06-04 10:00:00.000000000 +0800</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Modify: 2024-06-04 09:30:00.000000000 +0800</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Change: 2024-06-04 09:30:00.000000000 +0800</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#  Birth: 2024-06-01 08:00:00.000000000 +0800</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 inode 号</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> example.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 12345 example.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看文件系统的 inode 使用情况</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -i</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Filesystem      Inodes  IUsed   IFree IUse% Mounted on</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda1      1310720  82345 1228375    7% /</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 通过 inode 号查找文件（在当前文件系统中）</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -inum</span><span style="color:#D19A66;"> 12345</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-inode-的大小与数量" tabindex="-1"><a class="header-anchor" href="#_5-3-inode-的大小与数量"><span>5.3 inode 的大小与数量</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 inode 大小和数量</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> dumpe2fs</span><span style="color:#D19A66;"> -h</span><span style="color:#98C379;"> /dev/sda1</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> inode</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Inode count:              1310720</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Inodes per group:         8192</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Inode size:               256</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ext4 的 inode 大小通常是 256 字节</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># xfs 的 inode 大小通常也是 256 字节，动态分配</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">inode 耗尽</p><p>每个文件系统创建时分配了固定数量的 inode（ext4），如果小文件太多，即使磁盘空间充足，也会因为 inode 用完而无法创建新文件：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 磁盘空间还有，但无法创建文件</span></span>
<span class="line"><span style="color:#61AFEF;">touch</span><span style="color:#98C379;"> newfile.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># touch: cannot touch &#39;newfile.txt&#39;: No space left on device</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 inode 使用率</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -i</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果 IUse% 接近 100%，需要删除无用文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查找大量小文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /var</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> f</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">wc</span><span style="color:#D19A66;"> -l</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="_5-4-数据块寻址" tabindex="-1"><a class="header-anchor" href="#_5-4-数据块寻址"><span>5.4 数据块寻址</span></a></h3><p>ext4 文件系统使用多级间接寻址来支持大文件：</p>`,8),i(d,{code:``}),o[3]||=n(`<div class="hint-container tip"><p class="hint-container-title">ext4 的 extents</p><p>现代 ext4 使用 <strong>extents</strong> 替代传统的间接块映射。一个 extent 描述一段连续的块区间（如&quot;块 1000-2000&quot;），比逐块映射高效得多。对于大文件的顺序写入，extents 可以显著减少元数据开销。</p></div><h2 id="_6-硬链接与软链接" tabindex="-1"><a class="header-anchor" href="#_6-硬链接与软链接"><span>6. 硬链接与软链接</span></a></h2><h3 id="_6-1-链接类型对比" tabindex="-1"><a class="header-anchor" href="#_6-1-链接类型对比"><span>6.1 链接类型对比</span></a></h3>`,3),i(d,{code:``}),o[4]||=n(`<h3 id="_6-2-硬链接" tabindex="-1"><a class="header-anchor" href="#_6-2-硬链接"><span>6.2 硬链接</span></a></h3><p>硬链接是同一个 inode 的多个目录项——它们指向完全相同的底层数据。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 创建硬链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#98C379;"> original.txt</span><span style="color:#98C379;"> hardlink.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 验证：两个文件名指向同一个 inode</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -li</span><span style="color:#98C379;"> original.txt</span><span style="color:#98C379;"> hardlink.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 12345 -rw-r--r-- 2 alice alice 100 Jun 4 10:00 hardlink.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 12345 -rw-r--r-- 2 alice alice 100 Jun 4 10:00 original.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ^^^^^ inode 号相同</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#                    ^ 硬链接数变为 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除原文件，硬链接仍然可以访问数据</span></span>
<span class="line"><span style="color:#61AFEF;">rm</span><span style="color:#98C379;"> original.txt</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> hardlink.txt</span><span style="color:#7F848E;font-style:italic;">    # ✅ 数据仍然存在</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改硬链接 = 修改原文件（因为同一个 inode）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;new content&quot;</span><span style="color:#ABB2BF;"> &gt;&gt; </span><span style="color:#98C379;">hardlink.txt</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 原文件（如果还存在）也会看到新内容</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>硬链接的限制：</strong></p><ol><li>不能跨文件系统（因为 inode 号在不同文件系统中可能重复）</li><li>不能对目录创建硬链接（防止目录环）</li><li>只有删除所有硬链接（链接数归零），数据块才会被释放</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 尝试对目录创建硬链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#98C379;"> /home</span><span style="color:#98C379;"> /home_link</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ln: /home: hard link not allowed for directory</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 为什么不允许？</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果允许目录硬链接，可能形成环：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /home/link -&gt; /  -&gt; home -&gt; link -&gt; / -&gt; ...</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 这会导致 find、du 等递归操作死循环</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-软链接-符号链接" tabindex="-1"><a class="header-anchor" href="#_6-3-软链接-符号链接"><span>6.3 软链接（符号链接）</span></a></h3><p>软链接是一个独立的文件，内容是另一个文件的<strong>路径</strong>。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 创建软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /usr/local/bin/python3</span><span style="color:#98C379;"> /usr/local/bin/python</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /usr/local/bin/python</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 alice alice 20 ... python -&gt; /usr/local/bin/python3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 软链接有自己的 inode</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -li</span><span style="color:#98C379;"> /usr/local/bin/python</span><span style="color:#98C379;"> /usr/local/bin/python3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 67890 lrwxrwxrwx 1 alice alice 20 ... python -&gt; /usr/local/bin/python3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 12345 -rwxr-xr-x 1 alice alice 8760 ... python3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ^^^^^ inode 号不同</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除原文件，软链接变成&quot;悬空链接&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">rm</span><span style="color:#98C379;"> /usr/local/bin/python3</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /usr/local/bin/python</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 alice alice 20 ... python -&gt; /usr/local/bin/python3</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /usr/local/bin/python</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cat: /usr/local/bin/python: No such file or directory</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>软链接的特点：</strong></p><ol><li>可以跨文件系统</li><li>可以对目录创建软链接</li><li>原文件删除后，软链接失效（悬空链接）</li><li>软链接有自己的权限，但实际访问权限由目标文件决定</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 常见软链接使用场景</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 版本管理</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /usr/local/python3.11</span><span style="color:#98C379;"> /usr/local/python3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 升级时只需修改软链接</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 兼容性映射</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /usr/bin/python3</span><span style="color:#98C379;"> /usr/bin/python</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 目录快捷方式</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /var/log/nginx</span><span style="color:#98C379;"> /home/alice/nginx-logs</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 多版本共存</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /etc/alternatives/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 系统通过 alternatives 机制管理软链接</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> update-alternatives</span><span style="color:#D19A66;"> --config</span><span style="color:#98C379;"> java</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-4-硬链接-vs-软链接完整对比" tabindex="-1"><a class="header-anchor" href="#_6-4-硬链接-vs-软链接完整对比"><span>6.4 硬链接 vs 软链接完整对比</span></a></h3><table><thead><tr><th>特性</th><th>硬链接</th><th>软链接</th></tr></thead><tbody><tr><td>inode</td><td>与原文件相同</td><td>独立的 inode</td></tr><tr><td>跨文件系统</td><td>❌</td><td>✅</td></tr><tr><td>链接目录</td><td>❌</td><td>✅</td></tr><tr><td>原文件删除后</td><td>仍可访问数据</td><td>变为悬空链接</td></tr><tr><td>文件大小</td><td>与原文件相同</td><td>路径字符串长度</td></tr><tr><td>权限显示</td><td>与原文件相同</td><td>lrwxrwxrwx（777）</td></tr><tr><td>创建命令</td><td><code>ln</code></td><td><code>ln -s</code></td></tr><tr><td>查找指向同一 inode 的文件</td><td><code>find -samefile</code></td><td><code>readlink</code></td></tr></tbody></table><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查找所有指向同一 inode 的硬链接</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -samefile</span><span style="color:#98C379;"> original.txt</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查找悬空的软链接</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> l</span><span style="color:#98C379;"> !</span><span style="color:#D19A66;"> -exec</span><span style="color:#98C379;"> test</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> {}</span><span style="color:#56B6C2;"> \\;</span><span style="color:#D19A66;"> -print</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 批量创建软链接</span></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#E06C75;"> dir</span><span style="color:#C678DD;"> in</span><span style="color:#98C379;"> conf</span><span style="color:#98C379;"> data</span><span style="color:#98C379;"> logs</span><span style="color:#ABB2BF;">; </span><span style="color:#C678DD;">do</span></span>
<span class="line"><span style="color:#61AFEF;">    ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /opt/app/</span><span style="color:#E06C75;">$dir</span><span style="color:#98C379;"> /var/app/</span><span style="color:#E06C75;">$dir</span></span>
<span class="line"><span style="color:#C678DD;">done</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-常用文件系统命令" tabindex="-1"><a class="header-anchor" href="#_7-常用文件系统命令"><span>7. 常用文件系统命令</span></a></h2><h3 id="_7-1-df-——-磁盘使用情况" tabindex="-1"><a class="header-anchor" href="#_7-1-df-——-磁盘使用情况"><span>7.1 df —— 磁盘使用情况</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本用法</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#7F848E;font-style:italic;">                    # 所有文件系统</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span><span style="color:#7F848E;font-style:italic;">                 # 人类可读格式</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -T</span><span style="color:#7F848E;font-style:italic;">                 # 显示文件系统类型</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -i</span><span style="color:#7F848E;font-style:italic;">                 # 显示 inode 使用情况</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出示例</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -hT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Filesystem     Type   Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda1      ext4   100G   45G   51G  47% /</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda2      ext4   500G  230G  246G  49% /home</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># tmpfs          tmpfs  7.8G  1.2M  7.8G   1% /tmp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只看特定文件系统</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span><span style="color:#98C379;"> /home</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> ext4</span><span style="color:#7F848E;font-style:italic;">        # 只看 ext4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 排除虚拟文件系统</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> -x</span><span style="color:#98C379;"> tmpfs</span><span style="color:#D19A66;"> -x</span><span style="color:#98C379;"> devtmpfs</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-du-——-目录空间占用" tabindex="-1"><a class="header-anchor" href="#_7-2-du-——-目录空间占用"><span>7.2 du —— 目录空间占用</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本用法</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#7F848E;font-style:italic;">                    # 当前目录下所有子目录大小</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -h</span><span style="color:#7F848E;font-style:italic;">                 # 人类可读格式</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#7F848E;font-style:italic;">                # 只显示总计</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#E5C07B;"> *</span><span style="color:#7F848E;font-style:italic;">              # 当前目录下各项目大小</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> --max-depth=1</span><span style="color:#7F848E;font-style:italic;">      # 只显示一级子目录</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出示例</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /var/</span><span style="color:#E5C07B;">*</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4.0K    /var/backups</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2.3G    /var/cache</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1.5G    /var/lib</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 256M    /var/log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 排序找出最大的目录</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /var/</span><span style="color:#E5C07B;">*</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rh</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 排除某些目录</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#D19A66;"> --exclude=</span><span style="color:#98C379;">&#39;*.iso&#39;</span><span style="color:#98C379;"> /home/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看指定目录的总大小</span></span>
<span class="line"><span style="color:#61AFEF;">du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /var/log</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-ls-——-列出目录内容" tabindex="-1"><a class="header-anchor" href="#_7-3-ls-——-列出目录内容"><span>7.3 ls —— 列出目录内容</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 常用选项组合</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#7F848E;font-style:italic;">                # 所有文件（含隐藏）+ 详细信息</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lh</span><span style="color:#7F848E;font-style:italic;">                # 人类可读的文件大小</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lS</span><span style="color:#7F848E;font-style:italic;">                # 按文件大小排序</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lt</span><span style="color:#7F848E;font-style:italic;">                # 按修改时间排序</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lr</span><span style="color:#7F848E;font-style:italic;">                # 逆序</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -li</span><span style="color:#7F848E;font-style:italic;">                # 显示 inode 号</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lR</span><span style="color:#7F848E;font-style:italic;">                # 递归列出子目录</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看文件类型标识</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /dev</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># crw-rw-rw-  1 root root 1, 3 ... /dev/null</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># brw-rw----  1 root disk 8, 0 ... /dev/sda</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#  ^                   ^</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#  文件类型         设备号（主, 次）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -la</span><span style="color:#98C379;"> /usr/bin/python</span><span style="color:#E5C07B;">*</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># lrwxrwxrwx 1 root root 9 ... python -&gt; python3.10</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 按时间排序查看最近修改的文件</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#D19A66;"> -lt</span><span style="color:#98C379;"> /etc/</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-其他文件系统相关命令" tabindex="-1"><a class="header-anchor" href="#_7-4-其他文件系统相关命令"><span>7.4 其他文件系统相关命令</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># tree - 以树形结构显示目录</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#98C379;"> /etc/nginx</span><span style="color:#7F848E;font-style:italic;">           # 显示 nginx 配置树</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#D19A66;"> -L</span><span style="color:#D19A66;"> 2</span><span style="color:#98C379;"> /</span><span style="color:#7F848E;font-style:italic;">               # 只显示 2 层</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> /var</span><span style="color:#7F848E;font-style:italic;">              # 只显示目录</span></span>
<span class="line"><span style="color:#61AFEF;">tree</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> -F</span><span style="color:#98C379;"> /opt</span><span style="color:#7F848E;font-style:italic;">           # 显示大小和类型标识</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># file - 检测文件类型</span></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /etc/passwd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/passwd: ASCII text</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /usr/bin/ls</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /usr/bin/ls: ELF 64-bit LSB pie executable</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">file</span><span style="color:#98C379;"> /dev/sda</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda: block special (8/0)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># stat - 显示文件详细元数据</span></span>
<span class="line"><span style="color:#56B6C2;">stat</span><span style="color:#98C379;"> /etc/passwd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   File: /etc/passwd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   Size: 2765            Blocks: 8          IO Block: 4096   regular file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Device: 802h/2050d      Inode: 131073      Links: 1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Access: (0644/-rw-r--r--)  Uid: (    0/    root)   Gid: (    0/    root)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Access: 2024-06-04 10:00:00.000000000 +0800</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Modify: 2024-05-20 08:30:00.000000000 +0800</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Change: 2024-05-20 08:30:00.000000000 +0800</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ln - 创建链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#98C379;"> target</span><span style="color:#98C379;"> hardlink</span><span style="color:#7F848E;font-style:italic;">        # 硬链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> target</span><span style="color:#98C379;"> symlink</span><span style="color:#7F848E;font-style:italic;">      # 软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -sf</span><span style="color:#98C379;"> target</span><span style="color:#98C379;"> symlink</span><span style="color:#7F848E;font-style:italic;">     # 强制覆盖已有软链接</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -snf</span><span style="color:#98C379;"> target</span><span style="color:#98C379;"> symlink</span><span style="color:#7F848E;font-style:italic;">    # 强制覆盖，不解引用目标（替换目录软链接）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># find - 查找文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &quot;*.conf&quot;</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /var</span><span style="color:#D19A66;"> -size</span><span style="color:#98C379;"> +100M</span><span style="color:#7F848E;font-style:italic;">       # 大于 100MB 的文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /tmp</span><span style="color:#D19A66;"> -mtime</span><span style="color:#98C379;"> +7</span><span style="color:#7F848E;font-style:italic;">         # 7天前修改的文件</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> l</span><span style="color:#D19A66;"> -xtype</span><span style="color:#98C379;"> l</span><span style="color:#7F848E;font-style:italic;">     # 查找悬空软链接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_8-文件系统类型" tabindex="-1"><a class="header-anchor" href="#_8-文件系统类型"><span>8. 文件系统类型</span></a></h2><h3 id="_8-1-常见文件系统对比" tabindex="-1"><a class="header-anchor" href="#_8-1-常见文件系统对比"><span>8.1 常见文件系统对比</span></a></h3><table><thead><tr><th>文件系统</th><th>最大文件</th><th>最大分区</th><th>日志</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>ext4</strong></td><td>16TB</td><td>1EB</td><td>✅</td><td>通用，Linux 默认</td></tr><tr><td><strong>xfs</strong></td><td>8EB</td><td>8EB</td><td>✅</td><td>大文件、高性能</td></tr><tr><td><strong>btrfs</strong></td><td>16EB</td><td>16EB</td><td>✅</td><td>快照、校验、子卷</td></tr><tr><td><strong>zfs</strong></td><td>16EB</td><td>256万亿ZB</td><td>✅</td><td>数据完整性、RAID</td></tr><tr><td><strong>vfat</strong></td><td>4GB</td><td>2TB</td><td>❌</td><td>U 盘、EFI 分区</td></tr><tr><td><strong>ntfs</strong></td><td>16EB</td><td>16EB</td><td>✅</td><td>Windows 兼容</td></tr><tr><td><strong>tmpfs</strong></td><td>-</td><td>-</td><td>❌</td><td>内存文件系统</td></tr><tr><td><strong>overlayfs</strong></td><td>-</td><td>-</td><td>-</td><td>容器层叠</td></tr></tbody></table><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看已挂载的文件系统类型</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -T</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看支持的文件系统类型</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /proc/filesystems</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 创建文件系统（格式化）</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mkfs.ext4</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#7F848E;font-style:italic;">       # 格式化为 ext4</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mkfs.xfs</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#7F848E;font-style:italic;">        # 格式化为 xfs</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mkfs.vfat</span><span style="color:#D19A66;"> -F</span><span style="color:#D19A66;"> 32</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#7F848E;font-style:italic;"> # 格式化为 FAT32</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 挂载文件系统</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mount</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#98C379;"> /mnt/data</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> mount</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> ext4</span><span style="color:#98C379;"> /dev/sdb1</span><span style="color:#98C379;"> /mnt/data</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 卸载</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> umount</span><span style="color:#98C379;"> /mnt/data</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-2-etc-fstab-——-开机自动挂载" tabindex="-1"><a class="header-anchor" href="#_8-2-etc-fstab-——-开机自动挂载"><span>8.2 /etc/fstab —— 开机自动挂载</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/fstab 格式</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># &lt;设备&gt;        &lt;挂载点&gt;  &lt;文件系统&gt;  &lt;挂载选项&gt;  &lt;dump&gt;  &lt;pass&gt;</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/sda1</span><span style="color:#98C379;">       /</span><span style="color:#98C379;">         ext4</span><span style="color:#98C379;">        defaults</span><span style="color:#D19A66;">    0</span><span style="color:#D19A66;">       1</span></span>
<span class="line"><span style="color:#61AFEF;">/dev/sda2</span><span style="color:#98C379;">       /home</span><span style="color:#98C379;">     ext4</span><span style="color:#98C379;">        defaults</span><span style="color:#D19A66;">    0</span><span style="color:#D19A66;">       2</span></span>
<span class="line"><span style="color:#E06C75;">UUID</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">xxxx-xxxx</span><span style="color:#61AFEF;">  /data</span><span style="color:#98C379;">     xfs</span><span style="color:#98C379;">         defaults</span><span style="color:#D19A66;">    0</span><span style="color:#D19A66;">       2</span></span>
<span class="line"><span style="color:#61AFEF;">tmpfs</span><span style="color:#98C379;">           /tmp</span><span style="color:#98C379;">      tmpfs</span><span style="color:#98C379;">       defaults,nosuid,nodev</span><span style="color:#D19A66;">  0</span><span style="color:#D19A66;">  0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 UUID 挂载（推荐，比设备名更稳定）</span></span>
<span class="line"><span style="color:#61AFEF;">blkid</span><span style="color:#98C379;"> /dev/sda1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda1: UUID=&quot;a1b2c3d4-e5f6-7890-abcd-ef1234567890&quot; TYPE=&quot;ext4&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看当前挂载信息</span></span>
<span class="line"><span style="color:#61AFEF;">mount</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">column</span><span style="color:#D19A66;"> -t</span></span>
<span class="line"><span style="color:#61AFEF;">findmnt</span><span style="color:#7F848E;font-style:italic;">                        # 树形显示</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /etc/mtab</span><span style="color:#7F848E;font-style:italic;">                  # 与 mount 输出相同</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">fstab 编辑注意事项</p><ol><li>使用 <code>UUID=</code> 而非 <code>/dev/sdX</code>——设备名在重启后可能变化（尤其是 USB 磁盘）</li><li>修改 fstab 后务必测试：<code>sudo mount -a</code>（挂载 fstab 中所有条目）</li><li>错误的 fstab 可能导致系统无法启动——编辑前先备份</li><li>根分区的 <code>pass</code> 设为 1，其他分区设为 2，表示 fsck 检查顺序</li></ol></div><h2 id="_9-实战案例" tabindex="-1"><a class="header-anchor" href="#_9-实战案例"><span>9. 实战案例</span></a></h2><h3 id="_9-1-磁盘空间满排查" tabindex="-1"><a class="header-anchor" href="#_9-1-磁盘空间满排查"><span>9.1 磁盘空间满排查</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 步骤1：查看磁盘使用</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /dev/sda1  50G  48G  0  100% /</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步骤2：找出大文件/目录</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /</span><span style="color:#E5C07B;">*</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rh</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 30G     /var</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 15G     /home</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2G      /usr</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步骤3：逐级深入</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /var/</span><span style="color:#E5C07B;">*</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rh</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 28G     /var/log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> du</span><span style="color:#D19A66;"> -sh</span><span style="color:#98C379;"> /var/log/</span><span style="color:#E5C07B;">*</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rh</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -10</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 27G     /var/log/nginx/access.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步骤4：处理大日志文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误做法：直接 rm 后磁盘空间可能不释放（进程仍持有文件句柄）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确做法：</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> truncate</span><span style="color:#D19A66;"> -s</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> /var/log/nginx/access.log</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 或者</span></span>
<span class="line"><span style="color:#ABB2BF;">&gt; /var/log/nginx/access.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步骤5：验证</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">rm 不释放空间？</p><p>当一个进程正在写入日志文件时，即使你 <code>rm</code> 了文件，磁盘空间也不会释放——因为进程仍持有该文件的文件描述符。解决方法：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方法1：截断文件</span></span>
<span class="line"><span style="color:#ABB2BF;">&gt; /var/log/nginx/access.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法2：重启写入该文件的进程</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> systemctl</span><span style="color:#98C379;"> restart</span><span style="color:#98C379;"> nginx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法3：查找持有已删除文件的进程</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> lsof</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> deleted</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># nginx  1234  root  5w  REG  8,1  27000000000  12345 /var/log/nginx/access.log (deleted)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 然后重启该进程</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> systemctl</span><span style="color:#98C379;"> restart</span><span style="color:#98C379;"> nginx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="_9-2-inode-耗尽排查" tabindex="-1"><a class="header-anchor" href="#_9-2-inode-耗尽排查"><span>9.2 inode 耗尽排查</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 现象：磁盘有空间但无法创建文件</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -h</span><span style="color:#7F848E;font-style:italic;">    # 有空间</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#D19A66;"> -i</span><span style="color:#7F848E;font-style:italic;">    # inode 100%</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查找大量小文件</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> find</span><span style="color:#98C379;"> /var</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> f</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">wc</span><span style="color:#D19A66;"> -l</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 5,000,000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 找出文件最多的目录</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> find</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -xdev</span><span style="color:#D19A66;"> -printf</span><span style="color:#98C379;"> &#39;%h\\n&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">uniq</span><span style="color:#D19A66;"> -c</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rn</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -20</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 典型原因：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. /var/spool/clientmqueue（cron 邮件堆积）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. /tmp/session_*（PHP session 文件）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. /var/cache/（缓存文件堆积）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 清理</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> find</span><span style="color:#98C379;"> /var/spool/clientmqueue</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> f</span><span style="color:#D19A66;"> -delete</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-3-软链接维护" tabindex="-1"><a class="header-anchor" href="#_9-3-软链接维护"><span>9.3 软链接维护</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查找系统中的悬空链接</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> /usr</span><span style="color:#D19A66;"> -type</span><span style="color:#98C379;"> l</span><span style="color:#98C379;"> !</span><span style="color:#D19A66;"> -exec</span><span style="color:#98C379;"> test</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> {}</span><span style="color:#56B6C2;"> \\;</span><span style="color:#D19A66;"> -print</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 批量修复 Java 软链接</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> update-alternatives</span><span style="color:#D19A66;"> --install</span><span style="color:#98C379;"> /usr/bin/java</span><span style="color:#98C379;"> java</span><span style="color:#98C379;"> /usr/lib/jvm/java-17/bin/java</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> update-alternatives</span><span style="color:#D19A66;"> --config</span><span style="color:#98C379;"> java</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 替换目录软链接（原子操作）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误：先删后建，中间有窗口期</span></span>
<span class="line"><span style="color:#61AFEF;">rm</span><span style="color:#98C379;"> /opt/app/current</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /opt/app/v2</span><span style="color:#98C379;"> /opt/app/current</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确：使用 ln -snf</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -snf</span><span style="color:#98C379;"> /opt/app/v2</span><span style="color:#98C379;"> /opt/app/current</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 更安全：使用 mv -T（原子替换）</span></span>
<span class="line"><span style="color:#61AFEF;">ln</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> /opt/app/v2</span><span style="color:#98C379;"> /opt/app/current.tmp</span></span>
<span class="line"><span style="color:#61AFEF;">mv</span><span style="color:#D19A66;"> -Tf</span><span style="color:#98C379;"> /opt/app/current.tmp</span><span style="color:#98C379;"> /opt/app/current</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_10-总结" tabindex="-1"><a class="header-anchor" href="#_10-总结"><span>10. 总结</span></a></h2><table><thead><tr><th>知识点</th><th>关键内容</th></tr></thead><tbody><tr><td>一切皆文件</td><td>统一接口访问普通文件、设备、管道、Socket</td></tr><tr><td>FHS 标准</td><td>定义目录结构与用途，/etc /var /usr /proc /sys</td></tr><tr><td>/etc</td><td>系统配置文件中心</td></tr><tr><td>/var</td><td>可变数据（日志、缓存、队列）</td></tr><tr><td>/usr</td><td>用户级程序，/usr/local 是本地编译安装</td></tr><tr><td>/proc</td><td>虚拟文件系统，内核与进程信息</td></tr><tr><td>/sys</td><td>内核设备树，硬件拓扑</td></tr><tr><td>inode</td><td>文件元数据（权限、时间、块指针），不含文件名</td></tr><tr><td>硬链接</td><td>同一 inode 的多个目录项，不能跨文件系统</td></tr><tr><td>软链接</td><td>独立文件存储路径，可跨文件系统</td></tr><tr><td>df -i</td><td>检查 inode 使用情况</td></tr><tr><td>du -sh</td><td>检查目录空间占用</td></tr></tbody></table><p>理解 Linux 文件系统是掌握 Linux 的基础。无论是排查磁盘满问题、理解权限模型，还是管理链接和挂载，都离不开对目录结构和 inode 的深入理解。正如鸟哥在《Linux 私房菜》中所说：&quot;Linux 最重要的就是文件系统，搞懂了文件系统，Linux 就学通了一半。&quot;</p>`,42)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};